/* 10000 to 4096 */
#define VPQ_HWRAP_10000_TO_4K(_x)	(((_x)<<12)/10000)
/* 4096 to 10000 */
#define VPQ_HWRAP_4K_TO_10000(_x)	(((_x)*10000)/4096)

